INSERT INTO `assessment_questions` VALUES (1,'听力：What does the woman mean? (Audio clip about weekend plans)','[\"A. She likes to travel\", \"B. She works at a hospital\", \"C. She is studying medicine\", \"D. She wants to be a teacher\"]',1,'speaking','B1',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(2,'Reading: Choose the best word to fill in the blank.\n\n\"The company has _____ its profits by 20% this year.\"','[\"A. increased\", \"B. decreased\", \"C. maintained\", \"D. predicted\"]',1,'reading','B1',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(3,'Speaking: Describe your favorite food. What is it? Why do you like it? How often do you eat it?','[]',0,'speaking','B1',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(4,'Grammar: Choose the correct sentence.','[\"A. She don\'t like coffee\", \"B. She doesn\'t likes coffee\", \"C. She doesn\'t like coffee\", \"D. She not like coffee\"]',3,'grammar','A2',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(5,'听力：Where does this conversation probably take place? (Audio clip about ordering food)','[\"A. In a library\", \"B. In a restaurant\", \"C. In a hospital\", \"D. In a classroom\"]',2,'speaking','A2',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(6,'Reading: What is the main idea of the passage?\n\n\"Climate change has become one of the most pressing issues of our time. Scientists warn that rising temperatures could lead to severe consequences including extreme weather events, sea level rise, and biodiversity loss.\"','[\"A. Weather is unpredictable\", \"B. Climate change poses serious threats\", \"C. Scientists disagree on climate issues\", \"D. Biodiversity is decreasing naturally\"]',2,'reading','B2',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(7,'Speaking: Talk about a memorable trip you have taken. Where did you go? Who did you go with? What made it special?','[]',0,'speaking','B2',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(8,'Grammar: \"If I _____ rich, I would travel around the world.\"','[\"A. am\", \"B. was\", \"C. were\", \"D. be\"]',3,'grammar','B1',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(9,'听力：What is the speaker\'s attitude toward the proposal? (Audio clip about a business plan)','[\"A. Enthusiastic\", \"B. Skeptical\", \"C. Neutral\", \"D. Confused\"]',2,'speaking','B2',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(10,'Reading: According to the text, which statement is TRUE?\n\n\"Regular exercise has been shown to improve both physical and mental health. Studies indicate that even 30 minutes of moderate activity per day can reduce the risk of heart disease by up to 30%.\"','[\"A. Exercise only benefits physical health\", \"B. 30 minutes of daily exercise can lower heart disease risk\", \"C. Mental health is unrelated to exercise\", \"D. Only intense exercise provides health benefits\"]',2,'reading','B1',0,'2026-06-24 08:38:56','2026-07-03 19:19:46'),(11,'Speaking: Please introduce yourself. Talk about your name, where you are from, what you do, and your hobbies.','[]',1,'speaking','A1',0,'2026-06-26 19:36:03','2026-07-03 19:19:46'),(12,'Speaking: What is your favorite color? Describe it and explain why you like it.','[]',1,'speaking','A1',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(13,'Speaking: Describe your daily routine. What do you usually do in the morning, afternoon, and evening?','[]',1,'speaking','A2',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(14,'Speaking: Talk about your best friend. What is their name? What do they look like? What do you like about them?','[]',1,'speaking','A2',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(15,'Speaking: Describe a skill you would like to learn. Why does it interest you? How would you go about learning it?','[]',1,'speaking','B1',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(16,'Speaking: Talk about a movie or book that left a deep impression on you. What was it about and why did it affect you?','[]',1,'speaking','B1',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(17,'Speaking: If you could change one thing about the education system in your country, what would it be and why?','[]',1,'speaking','B2',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(18,'Speaking: Discuss the advantages and disadvantages of working remotely versus working in an office.','[]',1,'speaking','B2',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(19,'Speaking: In your opinion, what role should artificial intelligence play in education? Discuss both the potential benefits and risks.','[]',1,'speaking','C1',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(20,'Speaking: Some people believe that learning a foreign language changes the way you think. Do you agree or disagree? Explain your reasoning with specific examples.','[]',1,'speaking','C1',0,'2026-07-03 19:11:37','2026-07-03 19:19:46'),(21,'Read the following sentence aloud: \"The cat sat on the mat.\"','[]',1,'pronunciation','A1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(22,'Read the following sentence aloud: \"She bought a beautiful dress for the party.\"','[]',1,'pronunciation','A2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(23,'Read the paragraph aloud: \"Last summer, I visited my grandparents in the countryside. The weather was warm and sunny every day.\"','[]',1,'pronunciation','B1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(24,'Read the passage aloud: \"The rapid advancement of technology has fundamentally changed how we communicate, work, and learn.\"','[]',1,'pronunciation','B2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(25,'Read the passage aloud with proper intonation: \"While some argue that globalization benefits all nations equally, evidence suggests otherwise.\"','[]',1,'pronunciation','C1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(26,'Describe your family in 30 seconds. How many people are in your family?','[]',1,'fluency','A1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(27,'Talk about your last weekend. Where did you go? What did you do?','[]',1,'fluency','A2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(28,'Describe a memorable experience from your life and what you learned from it.','[]',1,'fluency','B1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(29,'Some people prefer big cities while others prefer small towns. Which do you prefer and why?','[]',1,'fluency','B2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(30,'Discuss the impact of social media on interpersonal relationships.','[]',1,'fluency','C1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(31,'Choose the correct sentence:','[\"A. He go to school every day\", \"B. He goes to school every day\", \"C. He going to school\", \"D. He gone to school\"]',2,'grammar','A1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(32,'She _____ to the store when it started raining.','[\"A. walk\", \"B. was walking\", \"C. walks\", \"D. walked\"]',2,'grammar','A2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(33,'If I _____ about the meeting earlier, I would have attended.','[\"A. knew\", \"B. have known\", \"C. had known\", \"D. would know\"]',3,'grammar','B1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(34,'The project, _____ was launched last month, has already gained traction.','[\"A. that\", \"B. which\", \"C. what\", \"D. who\"]',2,'grammar','B2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(35,'Not until the results were announced _____ the true impact.','[\"A. did we understand\", \"B. we understood\", \"C. we did understand\", \"D. understood we\"]',1,'grammar','C1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(36,'The weather is very _____ today. Let us go to the beach!','[\"A. sunny\", \"B. rainy\", \"C. snowy\", \"D. foggy\"]',1,'vocabulary','A1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(37,'She was very _____ after winning the competition.','[\"A. sad\", \"B. excited\", \"C. tired\", \"D. bored\"]',2,'vocabulary','A2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(38,'The speaker argument was so _____ that everyone was convinced.','[\"A. compelling\", \"B. boring\", \"C. simple\", \"D. confusing\"]',1,'vocabulary','B1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(39,'The research has _____ our understanding of climate change.','[\"A. maintained\", \"B. diminished\", \"C. revolutionized\", \"D. preserved\"]',3,'vocabulary','B2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(40,'His _____ remarks during the debate drew sharp criticism.','[\"A. diplomatic\", \"B. incendiary\", \"C. benevolent\", \"D. innocuous\"]',2,'vocabulary','C1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(41,'Imagine you are at a restaurant. What would you say to order food?','[]',1,'interaction','A1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(42,'A foreign visitor asks you for directions. What would you say?','[]',1,'interaction','A2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(43,'You are in a job interview. The interviewer asks: \"Why should we hire you?\" Respond.','[]',1,'interaction','B1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(44,'Give constructive feedback to a colleague about their presentation.','[]',1,'interaction','B2',1,'2026-07-03 19:19:46','2026-07-03 19:19:46'),(45,'Negotiate with a client who is hesitant about the price. Persuade them politely.','[]',1,'interaction','C1',1,'2026-07-03 19:19:46','2026-07-03 19:19:46');
