  CONSTRAINT `fk_conv_msg_session` FOREIGN KEY (`session_id`) REFERENCES `conversation_sessions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=335 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='对话消息表';
