INSERT INTO `discussion_posts` VALUES (4,4,'What is the best way to improve English speaking fluency?','I think the key is consistent practice every day. Even 15 minutes of speaking out loud makes a huge difference. I\'ve been doing shadow reading for 3 months and my fluency improved a lot.',5,2,'2026-06-25 00:20:39','2026-06-25 00:20:39'),(5,8,'Tips for reducing accent in English?','Shadow reading has been the most effective method for me. I listen to BBC podcasts and repeat after the speaker. Also recording myself and comparing with native speakers helps a lot.',3,1,'2026-06-24 21:20:39','2026-06-24 21:20:39'),(6,3,'How to prepare for IELTS speaking test?','Focus on coherence and fluency first. Many students worry too much about vocabulary but forget about natural flow. Practice with a timer and record yourself to review later.',7,3,'2026-06-24 02:20:39','2026-06-24 02:20:39'),(7,4,'What is the best way to improve English speaking fluency?','I think the key is consistent practice every day. Even 15 minutes of speaking out loud makes a huge difference. I\'ve been doing shadow reading for 3 months and my fluency improved a lot.',5,2,'2026-06-26 00:34:27','2026-06-26 00:34:27'),(8,8,'Tips for reducing accent in English?','Shadow reading has been the most effective method for me. I listen to BBC podcasts and repeat after the speaker. Also recording myself and comparing with native speakers helps a lot.',3,1,'2026-06-25 21:34:27','2026-06-25 21:34:27'),(9,3,'How to prepare for IELTS speaking test?','Focus on coherence and fluency first. Many students worry too much about vocabulary but forget about natural flow. Practice with a timer and record yourself to review later.',7,3,'2026-06-25 02:34:27','2026-06-25 02:34:27'),(10,4,'2','23呃1',1,2,'2026-06-26 02:43:59','2026-06-26 02:45:22'),(11,4,'has','hao',0,0,'2026-06-27 00:46:55','2026-06-27 00:46:55');
/*!40000 ALTER TABLE `discussion_posts` ENABLE KEYS */;
