LOCK TABLES `knowledge_documents` WRITE;
/*!40000 ALTER TABLE `knowledge_documents` DISABLE KEYS */;
INSERT INTO `knowledge_documents` VALUES (1,'如何开始使用 Lingolab？','注册账号后，系统会引导您完成英语水平测评。测评完成后即可使用发音评测、AI 对话等全部学习功能。','product_use','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(2,'发音评测是如何工作的？','系统使用 AI 语音识别技术分析您的发音，从音素准确度、重音、连读、语调、节奏五个维度进行评分，并给出具体的改进建议。','product_use','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(3,'AI 对话支持哪些场景？','目前支持自我介绍、问路、购物、餐厅点餐四个日常场景，以及面试、服务、导游三个角色扮演场景。我们会持续增加更多场景。','product_use','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(4,'如何提高我的 CEFR 等级？','坚持每日练习是关键。系统会根据您的薄弱项推荐针对性练习，建议每天完成 3 个学习任务（约 20-30 分钟），持续 2-3 个月通常可以提升一个等级。','study_advice','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(5,'录音时提示未检测到语音怎么办？','请检查麦克风权限是否已开启，确保在安静环境中录音，嘴巴距离麦克风 15-30 厘米。如果问题持续，尝试刷新页面或更换浏览器。','tech_issue','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(6,'支持哪些浏览器？','系统支持 Chrome 90+、Edge 90+、Firefox 88+ 浏览器。推荐使用 Chrome 以获得最佳体验。移动端请使用浏览器访问，暂不支持微信内置浏览器。','tech_issue','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(7,'如何查看我的学习进度？','点击顶部导航的「学习进度」，可以查看雷达图（五维能力）、趋势折线图（分数变化）和日历热力图（打卡记录）。','product_use','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(8,'积分和勋章有什么用？','积分反映您的学习投入度，勋章是对特定成就的认可。完成每日任务、闯关、配音挑战都可以获得积分和勋章。','product_use','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(9,'可以退款吗？','Lingolab 基础功能完全免费。如有付费项目需要退款，请发送邮件至 support@lingolab.ai 说明情况，我们会在 3 个工作日内处理。','refund','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(10,'如何联系人工客服？','如果智能客服无法解决您的问题，请发送邮件至 support@lingolab.ai，我们的客服团队会在 24 小时内回复。','general','faq',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(11,'业务流程介绍文档','# Lingolab 业务流程介绍文档> 面向客户演示与产品介绍，按学习者、教师、运营三类角色介绍业务流程。---','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(12,'一、用户端 — 从测评定级到持续提升的完整学习流程','用户端是系统的核心，覆盖用户从零基础入门到持续提升的全过程。整体流程分为三个阶段：```┌────────── 入口阶段 ──────────┐    ┌────────── 循环阶段 ──────────────────┐│                              │    │                                      ││  注册画像 → 水平测评 → 路径规划 ──→ 每日学习 → 动态画像更新 → 任务调整 ──┘│                              │    │   ↑                        ││   (一次性，建立初始画像)        │    │   └────── 数据回流 ─────────┘│                              │    │└──────────────────────────────┘    │  观测层：进度追踪 + 效果预测 + 预警                                    └──────────────────────────────────────┘```- **入口阶段**（一次性）：注册画像 → 水平测评 → 初始路径规划，建立用户初始画像和 CEFR 定级- **循环阶段**（持续运行）：每日学习 → 训练数据写入画像 → EMA 重算各维度分数 → 识别新短板 → 调整后续任务 → 继续学习，形成\"越学越精准\"的正反馈闭环- **观测层**（伴随运行）：进度可视化、效果预测、预警提醒，全程监控学习状态但不参与闭环回流### 1.1 注册与画像构建```用户注册 → 填写个人信息（年龄、学习目标、偏好） → 构建多维画像```用户首次使用系统时，通过手机号或邮箱注册账号，填写年龄、学习目标（日常交流/考试备考/商务英语/出国旅行/兴趣爱好）等信息。系统据此构建用户多维画像，作为后续个性化服务的数据基础。### 1.2 水平智能测评```进入测评 → 自适应答题（听力/口语/阅读/语法四维度） → CEFR 定级 → 能力雷达图```注册完成后，用户进入水平测评环节。系统采用自适应难度算法，根据用户答题情况动态调整题目难度，从听力、口语、阅读、语法四个维度全面评估英语水平。测评完成后输出 CEFR 等级（A1-C2）和各维度能力雷达图，精准定位用户的优势与短板。### 1.3 个性化学习路径规划```测评结果 + 用户画像 → 知识图谱匹配 → 拓扑排序 → 每日学习任务推送```基于测评结果和用户画像，系统利用知识图谱（129个知识点节点 + 292条前置依赖边）和 NetworkX 拓扑排序算法，为每位用户生成最优学习路径。每日自动推送学习任务，包括单词学习、发音跟读、AI 对话、听力训练等。### 1.4 每日学习训练学习者在系统内完成四大核心训练：**AI 智能对话练习**```选择场景 → 语音输入 → ASR 转写 → LLM 生成回复 → TTS 语音输出 → 继续对话```支持餐厅点餐、酒店入住、商务谈判、学术讨论、旅行出行等 8 大真实场景，端到端语音交互延迟 ≤ 2 秒。对话结束后，系统自动将发音评分和文本评分（语法正确率、词汇丰富度、对话参与度）摄入动态画像。**发音评测与纠错**```选择内容 → 跟读录音 → wav2vec2 声学分析 → GOP 音素评分 → 五维评分报告 → 纠音练习```用户跟读标准发音后，系统从音素准确度、重音、连读、语调、节奏五个维度进行精细评分。评分结果自动写入用户技能分数表，触发画像重算。**情景角色扮演**```选择角色（面试者/服务员/导游等） → 多轮互动对话 → 四维评分报告```用户选择角色后与 AI 进行多轮互动，系统从角色贴合度、语言恰当性、流利度、语法准确性四个维度进行评分。**语法纠错与润色**```输入文本或语音 → LLM 分析 → 错误标注 + 纠正版本 + 地道表达推荐```支持语音和文字双模态输入，实时识别时态、主谓一致、冠词、介词搭配等语法错误，提供纠正版本和更地道的表达方式。### 1.5 动态画像更新 — 核心闭环```训练完成 → 分数摄入 → EMA 重算各维度 → 更新用户等级 → 重新识别短板 → 调整后续任务```这是系统\"越学越精准\"的关键机制，每次训练后自动触发：| 步骤 | 触发时机 | 具体动作 ||------|----------|----------|| ① 分数摄入 | 发音评测/对话练习/任务完成 | `profile_updater.ingest_*()` 将评分写入 `UserSkillScore` 表 || ② EMA 重算 | 每次分数摄入后自动调用 | 指数移动平均算法，新分数权重 30%，历史分数权重 70%，只计算最近 30 天 || ③ 等级更新 | EMA 重算完成后 | 根据综合分更新 `user_profiles.level_final`（A1-C2），用户画像等级随之变化 || ④ 短板识别 | 下次路径规划/推荐时 | 推荐服务读取最新各维度 EMA 分数，自动识别最低分维度作为当前短板 || ⑤ 任务调整 | 每日任务生成时 | 优先推荐短板相关任务，难度匹配当前等级，确保学习始终\"对症下药\" |**举例说明**：用户初始测评等级为 B1，经过一周发音练习后，发音维度 EMA 分数从 55 提升到 68，但语法维度降至 50 成为新短板。系统自动将后续任务从\"发音跟读\"调整为\"语法纠错 + 对话练习\"，实现动态自适应。### 1.6 学习进度可视化```学习数据汇聚 → 雷达图 + 趋势折线图 + 日历热力图 + 统计卡片```系统以可视化图表展示用户的多维度学习进步轨迹，用户可切换天/周/月/全部时间范围查看，清晰了解自己的成长路径。雷达图展示的维度分数直接来自动态画像的 EMA 计算值。### 1.7 学习效果预测与预警```历史数据 → 线性回归预测 → 预计达标时间 → 偏差预警 → 反馈调整学习路径```系统基于用户历史学习数据进行线性回归分析，预测达到目标水平的时间和进度风险。当检测到连续未学习、学习时长下降超过 50%、发音得分停滞等异常情况时，自动触发预警提醒，并反馈调整学习路径。### 1.8 激励与社交**游戏化闯关**```每日闯关 → 配音挑战 → 获得积分 → 解锁勋章 → 排行榜竞争```**学习社区**```语音挑战广场 → 讨论区发帖 → 加入学习小组 → 组队学习 → 互评互助```### 1.9 智能客服学习中遇到任何问题，可随时通过语音或文字向智能客服咨询，LLM 驱动 7×24 小时在线解答。---','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(13,'二、教师端 — 班级管理与作业点评的完整教学工具','教师端为教师提供班级管理、作业布置、学生评估的一站式工具。### 2.1 班级管理```创建班级 → 生成邀请码 → 学生凭码加入 → 查看班级学生列表```教师创建班级后系统自动生成唯一邀请码，学生输入邀请码即可加入班级。教师可随时查看班级学生列表，了解每位学生的累计学习时长。### 2.2 作业布置```选择班级 → 设置作业标题 → 选择作业类型 → 设定截止日期 → 发布作业```教师可向指定班级布置定制化口语作业，作业类型包括跟读练习、对话练习、角色扮演。学生端自动收到作业通知。### 2.3 作业批阅与点评```查看学生提交 → 播放录音 → 在线评分 → 文字点评 → 学生收到反馈```教师查看学生提交的录音作业，系统自动给出 AI 初评分数作为参考，教师可调整评分并撰写文字点评。学生端实时收到教师的反馈。### 2.4 学生能力报告```选择学生 → 能力雷达图 → 进步趋势 → 活动记录 → 薄弱点分析```教师可查看每位学生的详细能力报告，包括多维度能力雷达图、历史进步趋势、近期活动记录等，帮助教师精准发现学生的共性薄弱点，调整教学策略。---','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(14,'三、运营端 — 平台运营与数据监控的管理后台','运营端为平台运营人员提供用户管理、内容管理、数据分析和反馈处理的全套工具。### 3.1 运营数据仪表盘```登录后台 → 运营看板 → 核心指标一览```运营看板展示平台核心运营指标：- **DAU/MAU**：日活跃用户数 / 月活跃用户数- **新增用户**：近 30 天注册趋势- **留存率**：D1（次日留存）/ D7（七日留存）- **内容统计**：各类学习资源数量分布- **用户角色分布**：学习者 / 教师 / 管理员占比### 3.2 用户管理```查看用户列表 → 搜索筛选 → 查看详情 → 禁用/启用账号 → 操作审计```运营人员可按用户名搜索、按角色筛选用户，查看用户详细信息和学习数据，对违规账号进行禁用或启用操作。### 3.3 内容管理```选择内容类型 → 查看/新增/编辑/删除 → 素材库维护```运营人员管理平台全部学习内容，包括：- **学习资源**：视频、音频、文章、练习题- **配音素材**：影视片段、动画片段- **挑战题库**：每日闯关题目、语音挑战题目### 3.4 反馈管理```查看用户反馈 → 筛选状态 → 查看详情 → 回复处理 → 标记已处理```集中管理用户提交的反馈和投诉，支持按状态筛选（待处理/已回复/已关闭），运营人员可直接回复用户并标记处理状态。### 3.5 操作日志审计所有管理员操作自动记录到操作日志，包括操作人、操作类型、操作对象、操作时间，确保平台运营安全可追溯。---','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(15,'四、三端协作关系','```┌──────────────────────────────────────────────────────────────┐│                       Lingolab 平台                            ││                                                                ││  ┌──────────────┐    ┌──────────────┐    ┌──────────────┐    ││  │    用户端      │    │    教师端      │    │    运营端      │    ││  │              │    │              │    │              │    ││  │ 注册测评      │    │ 班级管理      │    │ 用户管理      │    ││  │ 路径规划 ◄──┐│    │ 作业布置      │    │ 内容管理      │    ││  │ 每日训练 ──┐││    │ 提交点评      │    │ 数据仪表盘    │    ││  │ 动态画像 ◄─┘││   │ 学生报告      │    │ 反馈管理      │    ││  │ 进度追踪    ││    │              │    │ 操作日志      │    ││  │ 效果预测    ││    │              │    │              │    ││  │ 社区互动    ││    │              │    │              │    ││  └──────────────┘    └──────────────┘    └──────────────┘    ││         │                   │                   │              ││         └───────────────────┼───────────────────┘              ││                             │                                  ││                 核心 AI 能力层                                   ││  ASR（WhisperX）→ LLM（千问 qwen-plus）→ TTS（Edge TTS）       ││  发音评测（wav2vec2+GOP）  +  知识图谱（129节点/292边）          ││  动态画像（EMA 指数移动平均）                                    │└──────────────────────────────────────────────────────────────┘协作流程：  学习者每日训练 → 动态画像自动更新 → 路径规划自适应调整 → 持续精准提升  教师查看学生画像和报告 → 发现薄弱点 → 布置针对性作业 → 学生完成 → 数据回流  运营管理内容和用户 → 保障平台运转 → 学习者获得优质体验  智能客服 7×24h 三端全覆盖```---','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(16,'五、核心亮点总结','| 亮点 | 说明 ||------|------|| **动态画像闭环** | 每次训练后自动更新用户画像（EMA 算法），识别新短板，调整后续任务，实现\"越学越精准\" || **端到端语音交互** | ASR → LLM → TTS 全链路延迟 ≤ 2 秒，接近真人对话体验 || **专业级发音评测** | 五维音素级评分，远超市面\"跟读打分\"方案 || **动态画像系统** | EMA 指数移动平均算法，每次训练后自动重算用户等级和短板，驱动后续任务自适应调整 || **全年龄段覆盖** | 儿童到中老年，日常交流到商务谈判，一套系统全覆盖 || **三端协同** | C 端学习 + B 端教学管理 + 运营后台，完整商业闭环 || **成本可控** | LLM 使用国产千问，TTS 使用微软免费方案，ASR 和评测本地运行 |','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(17,'项目介绍','在全球化浪潮下，英语作为国际交流的核心语言，其重要性愈发显著。口语能力作为英语技能的关键一环，直接影响着人们在国际舞台上的交流与合作。然而，**传统英语口语学习**方式存在诸多弊端：课堂学习时间有限，学生练习机会不足，难以获得一对一的及时指导；市面上部分语言学习软件功能单一，无法满足多样化学习需求；线下培训机构成本高昂，时间和地点受限，难以满足学习者**随时随地学习**的迫切需求。基于此，本项目构建一款**基于自然语言处理和大语言模型技术**的英语口语训练系统，覆盖儿童、青少年、大学生、职场人士和中老年等全年龄段用户，通过AI驱动的个性化教学、实时语音评估、情景对话模拟等核心功能，为用户提供全天候、个性化的英语口语训练服务。','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(18,'项目行业','- **行业领域：** 在线教育 / 语言学习 / AI教育- **应用方向：** 英语口语评测、发音纠错、情景对话练习、自适应学习、语言能力评估','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(19,'项目功能','| 序号 | 功能模块             | 功能描述                                                     || ---- | -------------------- | ------------------------------------------------------------ || 1    | 用户注册与多维度画像 | 用户注册时采集年龄、英语水平（通过水平测试定级）、学习目标（日常交流/考试/商务）、学习偏好等信息，构建用户多维画像，为个性化学习提供数据基础 || 2    | 英语水平智能测评     | 提供包含听力、口语、阅读、语法四个维度的AI自适应测评，根据用户答题情况动态调整题目难度，精准定位用户的CEFR等级（A1-C2）和各维度能力短板 || 3    | 个性化学习路径规划   | 基于用户画像和水平测评结果，利用**强化学习算法**为每位用户定制专属学习路径，每日自动推送学习任务（单词、跟读、对话、听力），实现因材施教 || 4    | AI发音评测与纠错     | 用户跟读标准发音后，系统从音素级准确度、重音、连读、语调、节奏五个维度进行精细评分，通过音素级波形对比可视化展示发音问题，并生成针对性纠音练习 || 5    | 流利度与完整性评估   | 综合评估用户口语的语速、停顿频率、重复率、自我修正率等流利度指标，以及回答的逻辑完整性、内容相关性、语法正确性，给出综合口语能力评分 || 6    | 智能语音对话练习     | 基于大语言模型驱动AI虚拟对话伙伴，支持餐厅点餐、酒店入住、商务谈判、学术讨论、旅行出行等60+真实场景的沉浸式对话练习，AI可根据用户水平自动调整语速和用词难度 || 7    | AI语法纠错与润色     | 用户口语表达中的语法错误（时态、主谓一致、冠词等）被实时识别并给出纠正版本，同时提供更地道的表达方式推荐，帮助用户逐步提升语言质量 || 8    | 情景角色扮演         | 用户可选择角色（如面试者、导游、医生）与AI进行多轮互动角色扮演，系统根据角色设定和场景要求实时评价用户表达的恰当性和专业性 || 9    | 学习资料智能推荐     | 基于用户的兴趣偏好、学习记录和能力短板，利用协同过滤和内容推荐算法，从海量学习资源库（视频、音频、文章、练习题）中精准推荐合适的学习材料 || 10   | 游戏化闯关学习       | 设计语音闯关、单词PK、配音挑战、口语擂台等游戏化学习模块，用户通过完成口语任务获得积分和勋章，激发学习兴趣和持续学习的动力 || 11   | 学习社区与社交互动   | 内置学习社区，用户可建立学习小组、发起语音挑战、互相点评口语录音、参与话题讨论，系统提供AI辅助评分确保互评质量 || 12   | 学习进度可视化追踪   | 以雷达图、趋势曲线、能力热力图等可视化形式展示用户在学习时长、词汇量、发音准确率、流利度等维度的进步轨迹，让用户清晰看到成长 || 13   | 学习效果预测与预警   | 基于历史学习数据构建学习效果预测模型，预测用户达到目标水平的预计时间和进度风险，当用户连续学习时长下降或练习完成率低于阈值时发送提醒和激励 || 14   | 教师端教学管理后台   | 教师可通过后台查看所带班级学生的学习报告、能力分布、共性薄弱点，支持布置定制化口语作业、在线点评学生录音、发起班级口语比赛 || 15   | 运营管理后台         | 平台运营人员可管理用户账号、审核UGC内容、配置学习活动、查看平台运营数据（DAU/MAU、留存率、付费转化率）、处理用户反馈和投诉 || 16   | 智能客服与帮助系统   | 基于大语言模型的智能客服机器人，7×24小时解答用户关于产品使用、课程选择、技术问题等方面的咨询，支持语音和文字双模态交互 |','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37'),(20,'项目难点','1. **多年龄段、多口音的发音评测泛化能力：** 系统需覆盖从儿童（高音调、发音不清晰）到老年人（语速慢、音量低）的全年龄段用户，以及不同地域口音（中式、日式、印度式等）。构建能跨年龄段、跨口音稳定工作的统一评测模型，需要在音素级特征提取和声学模型训练上做大量优化，平衡各亚群的评测准确性。2. **大语言模型在口语场景的实时交互延迟控制：** 智能语音对话需要实现端到端延迟在2秒以内（接近真人对话节奏），涉及语音识别（ASR）→语义理解（NLU）→对话管理→回复生成→语音合成（TTS）的完整链路。如何在大模型推理延迟和回复质量之间取得平衡，采用流式处理和推测解码等技术降低延迟，是重要的技术挑战。3. **口语评分的主客观一致性保证：** AI评分需要与人工评分保持高度一致性（相关系数≥0.85），但在评分维度上存在主观性——如\"表达地道性\"和\"逻辑连贯性\"的评估标准难以量化。需要构建融合多维度、多粒度的评分体系，并持续用人工评分数据校准模型。 **逻辑分组**：账号体系（1）→ 能力评估（2）→ 学习过程（3-9）→ 激励留存（10-13）→ 管理工具（14-15）→ 系统支撑（16）','general','manual',1,'2026-07-02 15:01:37','2026-07-02 15:01:37');
/*!40000 ALTER TABLE `knowledge_documents` ENABLE KEYS */;
