INSERT INTO `post_comments` VALUES (7,4,8,'Totally agree! Consistency is key. I also recommend using language exchange apps.','2026-06-25 01:20:39'),(8,4,3,'Shadow reading is great. I\'ve been doing it for 6 months now.','2026-06-25 01:50:39'),(9,5,4,'BBC podcasts are excellent for learning British pronunciation.','2026-06-24 23:20:39'),(10,6,4,'Great advice! I think part 2 is the hardest, any tips for that?','2026-06-24 14:20:39'),(11,6,8,'For part 2, practice the 1-minute preparation strategy. Write down keywords, not full sentences.','2026-06-24 16:20:39'),(12,6,3,'Also don\'t forget to use discourse markers naturally - they help with coherence score.','2026-06-24 18:20:39'),(13,7,8,'Totally agree! Consistency is key. I also recommend using language exchange apps.','2026-06-26 01:34:27'),(14,7,3,'Shadow reading is great. I\'ve been doing it for 6 months now.','2026-06-26 02:04:27'),(15,8,4,'BBC podcasts are excellent for learning British pronunciation.','2026-06-25 23:34:27'),(16,9,4,'Great advice! I think part 2 is the hardest, any tips for that?','2026-06-25 14:34:27'),(17,9,8,'For part 2, practice the 1-minute preparation strategy. Write down keywords, not full sentences.','2026-06-25 16:34:27'),(18,9,3,'Also don\'t forget to use discourse markers naturally - they help with coherence score.','2026-06-25 18:34:27'),(19,10,4,'太好了','2026-06-26 02:44:10'),(20,10,4,'j','2026-06-26 02:45:22'),(21,5,4,'Could you elaborate more?','2026-06-25 11:59:56');
/*!40000 ALTER TABLE `post_comments` ENABLE KEYS */;
