INSERT INTO `pronunciation_content` VALUES (1,'基础问候','hello','word','A1','日常','/həˈloʊ/',NULL,'/static/pronunciation/pron_1.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(2,'感谢','thank you','word','A1','日常','/θæŋk juː/',NULL,'/static/pronunciation/pron_2.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(3,'请','please','word','A1','日常','/pliːz/',NULL,'/static/pronunciation/pron_3.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(4,'对不起','sorry','word','A1','日常','/ˈsɒri/',NULL,'/static/pronunciation/pron_4.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(5,'水','water','word','A1','日常','/ˈwɔːtər/',NULL,'/static/pronunciation/pron_5.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(6,'美丽的','beautiful','word','A2','形容词','/ˈbjuːtɪfəl/',NULL,'/static/pronunciation/pron_6.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(7,'重要的','important','word','A2','形容词','/ɪmˈpɔːrtənt/',NULL,'/static/pronunciation/pron_7.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(8,'经验','experience','word','A2','名词','/ɪkˈspɪəriəns/',NULL,'/static/pronunciation/pron_8.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(9,'成就','achievement','word','B1','名词','/əˈtʃiːvmənt/',NULL,'/static/pronunciation/pron_9.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(10,'环境','environment','word','B1','名词','/ɪnˈvaɪrənmənt/',NULL,'/static/pronunciation/pron_10.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(11,'机会','opportunity','word','B1','名词','/ˌɒpəˈtjuːnɪti/',NULL,'/static/pronunciation/pron_11.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(12,'可持续的','sustainable','word','B2','形容词','/səˈsteɪnəbl/',NULL,'/static/pronunciation/pron_12.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(13,'复杂性','complexity','word','B2','名词','/kəmˈpleksɪti/',NULL,'/static/pronunciation/pron_13.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(14,'自我介绍','My name is Tom. I am from China.','sentence','A1','日常',NULL,NULL,'/static/pronunciation/pron_14.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(15,'询问时间','What time is it now?','sentence','A1','日常',NULL,NULL,'/static/pronunciation/pron_15.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(16,'描述天气','The weather is nice today. Let\'s go for a walk.','sentence','A2','日常',NULL,NULL,'/static/pronunciation/pron_16.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(17,'点餐','I would like a cup of coffee and a sandwich, please.','sentence','A2','餐厅',NULL,NULL,'/static/pronunciation/pron_17.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(18,'表达观点','I believe that learning a new language opens up many opportunities.','sentence','B1','观点',NULL,NULL,'/static/pronunciation/pron_18.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(19,'商务会议','Could we schedule a meeting to discuss the project timeline?','sentence','B1','商务',NULL,NULL,'/static/pronunciation/pron_19.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(20,'学术讨论','The research findings suggest a significant correlation between practice frequency and pronunciation improvement.','sentence','B2','学术',NULL,NULL,'/static/pronunciation/pron_20.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41'),(21,'复杂表达','Despite the challenges we faced, the team managed to deliver the project ahead of schedule.','sentence','B2','商务',NULL,NULL,'/static/pronunciation/pron_21.mp3',1,'2026-06-26 08:19:30','2026-07-03 13:34:41');
