INSERT INTO `search_logs` VALUES (1,4,'如何练习发音？','[{\"id\": \"2\", \"score\": 0.5434, \"title\": \"发音评测是如何工作的？\"}, {\"id\": \"18\", \"score\": 0.4662, \"title\": \"项目行业\"}, {\"id\": \"1\", \"score\": 0.46, \"title\": \"如何开始使用 Lingolab？\"}]','你好！在 Lingolab，你可以通过「发音评测」功能练习发音 🌟  \n系统会用 AI 从音素准确度、重音、连读、语调、节奏五个维度实时评分，并给出具体改进建议。  \n注册并完成英语水平测评后，就能随时开启练习啦～需要我帮你一步步操作吗？😊','2026-07-02 15:12:52'),(2,4,'你好，你是谁','[{\"id\": \"18\", \"score\": 0.4171, \"title\": \"项目行业\"}, {\"id\": \"3\", \"score\": 0.3869, \"title\": \"AI 对话支持哪些场景？\"}, {\"id\": \"10\", \"score\": 0.3768, \"title\": \"如何联系人工客服？\"}]','你好呀！我是 Lingolab 的智能客服助手——小语 🌈  \n我在这里帮你解答英语学习、AI对话练习、发音评测、课程使用等方面的问题～  \n既专业又亲切，有问题尽管问，我会尽力帮你搞定！😊','2026-07-02 15:13:00'),(3,4,'如何提高等级','[{\"id\": \"4\", \"score\": 0.6323, \"title\": \"如何提高我的 CEFR 等级？\"}, {\"id\": \"20\", \"score\": 0.4484, \"title\": \"项目难点\"}, {\"id\": \"12\", \"score\": 0.4413, \"title\": \"一、用户端 — 从测评定级到持续提升的完整学习流程\"}]','你好！提升 CEFR 等级的关键是「坚持+精准练习」✨  \n系统会根据你的薄弱项推荐每日学习任务，建议每天完成 3 个（约 20–30 分钟），持续 2–3 个月，通常就能稳步升一级～  \n记得定期完成口语评测和阶段性测评，让动态画像帮你自动调整学习路径哦！需要我为你定制一个小目标计划吗？😊','2026-07-02 15:14:04'),(4,4,'这个项目的评分系统是怎么样的','[{\"id\": \"20\", \"score\": 0.599, \"title\": \"项目难点\"}, {\"id\": \"2\", \"score\": 0.5813, \"title\": \"发音评测是如何工作的？\"}, {\"id\": \"19\", \"score\": 0.5593, \"title\": \"项目功能\"}]','你好！Lingolab 的评分系统分为两个核心部分：\n\n✅ **发音评测**：从音素准确度、重音、连读、语调、节奏五个维度AI打分，每项独立反馈+改进建议；  \n✅ **综合能力等级（CEFR）**：基于水平测试 + 日常练习表现（如口语流利度、语法正确率、词汇运用等）动态评估，每完成阶段性测评自动更新等级。\n\n所有评分都结合你的年龄、口音特点和学习目标个性化校准，更公平、更精准～ 🌟','2026-07-02 15:14:21'),(5,4,'该项目的核心是什么','[{\"id\": \"17\", \"score\": 0.4602, \"title\": \"项目介绍\"}, {\"id\": \"11\", \"score\": 0.4338, \"title\": \"业务流程介绍文档\"}, {\"id\": \"14\", \"score\": 0.4255, \"title\": \"三、运营端 — 平台运营与数据监控的管理后台\"}]','Lingolab 的核心是：**用AI驱动个性化英语口语训练** 💡  \n它融合自然语言处理（NLP）与大语言模型技术，实现三大关键能力：  \n🔹 实时语音评估（精准到音素、语调、节奏）  \n🔹 情景化AI对话（覆盖生活、职场、考试等真实场景）  \n🔹 动态学习路径（根据你的弱项自动推荐练习，适配全年龄段）  \n\n一句话总结：让每个人都能拥有「专属的AI口语教练」 🌍✨','2026-07-02 15:15:01'),(6,4,'核心业务闭环','[{\"id\": \"16\", \"score\": 0.458, \"title\": \"五、核心亮点总结\"}, {\"id\": \"14\", \"score\": 0.439, \"title\": \"三、运营端 — 平台运营与数据监控的管理后台\"}, {\"id\": \"12\", \"score\": 0.4281, \"title\": \"一、用户端 — 从测评定级到持续提升的完整学习流程\"}]','Lingolab 的核心业务闭环是：  \n**测评定级 → 每日AI对话训练 → 五维发音+表达评分 → 动态画像更新（EMA算法）→ 自适应任务调整 → 下一轮训练**  \n\n这个闭环每完成一次，系统就更懂你一分，真正实现「越练越准、越学越快」🎯  \n就像一位会进化的AI教练，始终跟着你的节奏走～ 😊','2026-07-02 15:15:21'),(7,4,'口语水平怎么提升？','[{\"id\": \"18\", \"score\": 0.5766, \"title\": \"项目行业\"}, {\"id\": \"17\", \"score\": 0.5401, \"title\": \"项目介绍\"}, {\"id\": \"20\", \"score\": 0.5381, \"title\": \"项目难点\"}]','你好！提升口语水平，关键在于「多说、多听、及时反馈」😊  \nLingolab 正是为此设计的：通过 AI 实时发音评测、情景对话练习和个性化纠错，帮你像和真人对话一样自然开口。  \n每天坚持15分钟情景模拟（比如点餐、面试、旅行），系统会精准指出语音、语调、语法小问题～  \n需要我推荐适合你当前水平的练习路径吗？🙂','2026-07-02 15:19:12'),(8,4,'我最近过去时总学不会，有什么建议吗？','[{\"id\": \"4\", \"score\": 0.5637, \"title\": \"如何提高我的 CEFR 等级？\"}, {\"id\": \"7\", \"score\": 0.4921, \"title\": \"如何查看我的学习进度？\"}, {\"id\": \"19\", \"score\": 0.4846, \"title\": \"项目功能\"}]','小语来帮你啦！😊  \n过去时确实是英语入门的关键一步，建议先确保你已掌握【一般现在时】这个前置技能（知识图谱推荐里提到的哦～）。  \n\n你可以试试《Past Tense Mastery》这门课——它用生活场景+动词分类（规则/不规则）帮你轻松突破；搭配《A Wonderful Trip to London》小故事，边听边练，效果更好！  \n\n每天花15分钟专注练1个动词类型（比如今天专攻-ed规则','2026-07-02 15:27:41'),(9,4,'你好','[{\"id\": \"18\", \"score\": 0.426, \"title\": \"项目行业\"}, {\"id\": \"3\", \"score\": 0.4098, \"title\": \"AI 对话支持哪些场景？\"}, {\"id\": \"19\", \"score\": 0.3971, \"title\": \"项目功能\"}]','你好呀！😊 很高兴见到你～  \n是想了解英语学习功能、试试AI对话练习，还是遇到什么使用小问题？小语随时为你效劳！','2026-07-02 15:30:59'),(10,4,'我想要学习过去式','[{\"id\": \"4\", \"score\": 0.528, \"title\": \"如何提高我的 CEFR 等级？\"}, {\"id\": \"17\", \"score\": 0.4899, \"title\": \"项目介绍\"}, {\"id\": \"7\", \"score\": 0.4724, \"title\": \"如何查看我的学习进度？\"}]','你好！很高兴你想学过去式～😊  \n在 Lingolab，你可以通过「语法训练」模块找到「一般过去时」专项练习，系统会结合例句、发音、填空和情景对话帮你扎实掌握（比如 *I walked / She went / They didn’t call*）。  \n\n如果你刚接触，建议先完成前置技能「动词原形与规则变化」，再练习不规则动词表（我们有带音频的高频100词清单哦～）  \n\n需要我为你推荐一组入门','2026-07-02 15:31:16'),(11,20,'你好，你是谁','[{\"id\": \"18\", \"score\": 0.4171, \"title\": \"项目行业\"}, {\"id\": \"3\", \"score\": 0.3869, \"title\": \"AI 对话支持哪些场景？\"}, {\"id\": \"10\", \"score\": 0.3768, \"title\": \"如何联系人工客服？\"}]','你好！我是 Lingolab 的智能客服助手——小语 😊  \n我专门帮你解答英语学习、AI对话练习、账号使用等方面的问题，随时为你提供支持～  \n有什么想了解的，尽管告诉我吧！','2026-07-02 20:32:15'),(12,20,'我想学习过去时','[{\"id\": \"4\", \"score\": 0.5247, \"title\": \"如何提高我的 CEFR 等级？\"}, {\"id\": \"7\", \"score\": 0.511, \"title\": \"如何查看我的学习进度？\"}, {\"id\": \"17\", \"score\": 0.4887, \"title\": \"项目介绍\"}]','太棒了！过去时是英语基础语法的重要一环 🌟  \n建议从【一般过去时】开始（CEFR A1级别），它需要先掌握【一般现在时】作为前置基础。  \n你可以试试我们的课程《Past Tense Mastery》和情景故事《A Wonderful Trip to London》，边听边练，轻松掌握规则动词和不规则动词的变化哦～  \n需要我帮你找具体练习入口吗？ 😊','2026-07-02 20:32:25'),(13,20,'你可以为我做什么','[{\"id\": \"4\", \"score\": 0.4729, \"title\": \"如何提高我的 CEFR 等级？\"}, {\"id\": \"3\", \"score\": 0.4215, \"title\": \"AI 对话支持哪些场景？\"}, {\"id\": \"18\", \"score\": 0.4115, \"title\": \"项目行业\"}]','当然可以！😊  \n我可以为你：  \n✅ 解答 Lingolab 平台使用问题（注册、密码、课程、AI对话等）  \n✅ 推荐适合你水平的英语学习路径（比如过去时、发音、面试口语等）  \n✅ 帮你规划每日学习任务，助力 CEFR 等级提升  \n✅ 介绍 AI 对话练习场景（如点餐、问路、面试等）  \n\n就像一位懂你的学习伙伴～  \n你现在最想练哪一块？我来帮你安排！ 🌟','2026-07-02 20:32:37'),(14,20,'讲一讲该项目的核心业务','[{\"id\": \"11\", \"score\": 0.5863, \"title\": \"业务流程介绍文档\"}, {\"id\": \"17\", \"score\": 0.5584, \"title\": \"项目介绍\"}, {\"id\": \"19\", \"score\": 0.5381, \"title\": \"项目功能\"}]','Lingolab 的核心业务是：**用AI技术打造个性化英语口语训练平台**。  \n我们通过自然语言处理（NLP）和大语言模型，提供实时语音评估、情景对话模拟、智能纠错与反馈，覆盖全年龄段学习者。  \n所有学习内容都基于用户注册时构建的多维画像（如年龄、目标、水平）动态推荐，真正实现“千人千面”的口语提升。  \n简而言之：让每个人都能随时随地、高效自信地说英语 🌍💬','2026-07-02 20:32:57'),(15,4,'你好','[{\"id\": \"18\", \"score\": 0.426, \"title\": \"项目行业\"}, {\"id\": \"3\", \"score\": 0.4098, \"title\": \"AI 对话支持哪些场景？\"}, {\"id\": \"19\", \"score\": 0.3971, \"title\": \"项目功能\"}]','你好呀！😊 很高兴见到你～  \n是想了解英语学习方法、试试 AI 对话练习，还是遇到使用上的小问题？随时告诉我，小语都在这里帮你！','2026-07-03 08:44:41'),(16,4,'j介绍一下这个项目','[{\"id\": \"11\", \"score\": 0.5628, \"title\": \"业务流程介绍文档\"}, {\"id\": \"3\", \"score\": 0.5168, \"title\": \"AI 对话支持哪些场景？\"}, {\"id\": \"19\", \"score\": 0.4989, \"title\": \"项目功能\"}]','你好！很高兴为你介绍 Lingolab 项目～ 🌟  \n\nLingolab 是一个以「AI 驱动、场景真实、个性精准」为特色的英语学习平台。我们通过智能测评为每位用户定级，并结合学习目标（如日常交流、考试、商务）和偏好，定制专属学习路径。  \n\n目前 AI 对话已覆盖7大实用场景：自我介绍、问路、购物、餐厅点餐，以及面试、客户服务、导游等角色扮演，帮你边练边用、自然提升表达力！  \n\n需要我为你推','2026-07-03 08:44:54'),(17,4,'用户怎么注册','[{\"id\": \"12\", \"score\": 0.4672, \"title\": \"一、用户端 — 从测评定级到持续提升的完整学习流程\"}, {\"id\": \"1\", \"score\": 0.4569, \"title\": \"如何开始使用 Lingolab？\"}, {\"id\": \"14\", \"score\": 0.4533, \"title\": \"三、运营端 — 平台运营与数据监控的管理后台\"}]','注册超简单！只需三步👇  \n1️⃣ 访问 Lingolab 官网或打开 App，点击「立即注册」；  \n2️⃣ 输入手机号/邮箱 + 设置密码（支持微信快捷登录）；  \n3️⃣ 完成简短英语水平测评（约5–8分钟），系统即为你生成专属学习路径 ✅  \n\n注册后就能立刻使用发音评测、AI 对话、智能跟读等全部功能啦～  \n需要我帮你一步步引导测评入口吗？😊','2026-07-03 08:45:05'),(18,4,'如何练习发音？','[{\"id\": \"2\", \"score\": 0.5434, \"title\": \"发音评测是如何工作的？\"}, {\"id\": \"18\", \"score\": 0.4662, \"title\": \"项目行业\"}, {\"id\": \"1\", \"score\": 0.46, \"title\": \"如何开始使用 Lingolab？\"}]','你好！在 Lingolab，你可以通过「发音评测」功能高效练习发音 🌟  \n系统会从音素准确度、重音、连读、语调和节奏五个维度AI打分，并给出具体改进建议。  \n建议每天跟读1–2个短句，反复对比系统反馈，进步很快哦～需要我推荐适合你水平的发音练习内容吗？😊','2026-07-03 08:51:23'),(19,4,'口语水平怎么提升？','[{\"id\": \"18\", \"score\": 0.5766, \"title\": \"项目行业\"}, {\"id\": \"17\", \"score\": 0.5401, \"title\": \"项目介绍\"}, {\"id\": \"20\", \"score\": 0.5381, \"title\": \"项目难点\"}]','你好！提升口语水平，关键在于「多说、多听、多反馈」😊  \nLingolab 的 AI 口语教练能实时评测你的发音、语调和流利度，并针对中式口音等常见问题给出具体纠错建议。  \n每天坚持15分钟情景对话练习（比如点餐、面试、旅行），配合AI即时反馈，进步会特别明显～  \n需要我帮你推荐一个适合你当前水平的入门练习模块吗？ 😊','2026-07-03 10:46:12'),(20,25,'发音评测功能怎么用？','[{\"id\": \"2\", \"score\": 0.732, \"title\": \"发音评测是如何工作的？\"}, {\"id\": \"19\", \"score\": 0.6087, \"title\": \"项目功能\"}, {\"id\": \"20\", \"score\": 0.6047, \"title\": \"项目难点\"}]','你好呀～我是小语！😊  \n发音评测功能很简单：进入「口语训练」模块，选择任意句子或对话练习，点击麦克风朗读即可——系统会实时分析你的**音素准确度、重音、连读、语调和节奏**，并给出逐项评分和具体改进建议（比如：“/θ/ 发音偏弱，建议舌尖轻触上齿”）。  \n\n它还特别贴心，能适应不同年龄和口音（如中式、日式英语），帮你稳扎稳打提升自然度哦～  \n需要我推荐一个适合你当前水平的发音练习吗？✨','2026-07-03 18:08:45'),(21,25,'什么是自适应测评？','[{\"id\": \"2\", \"score\": 0.4588, \"title\": \"发音评测是如何工作的？\"}, {\"id\": \"18\", \"score\": 0.445, \"title