INSERT INTO `voice_challenges` VALUES (4,'Tongue Twister Challenge','挑战绕口令，看看谁的发音最标准！','She sells seashells by the seashore. The shells she sells are surely seashells.','2026-07-02 02:20:39',1,'2026-06-25 02:20:39'),(5,'BBC News Shadow Reading','跟读 BBC 新闻片段，练习英式发音和语调','The government has announced new measures to tackle climate change, including a ban on petrol cars by 2030.','2026-06-30 02:20:39',1,'2026-06-25 02:20:39'),(6,'Poem Recitation','朗诵经典英文诗歌，展现你的语音韵律感','Shall I compare thee to a summer\'s day? Thou art more lovely and more temperate.','2026-06-28 02:20:39',1,'2026-06-25 02:20:39');
